type OverlayAccessibleName = {
  'aria-label': string;
  'aria-labelledby'?: never;
} | {
  'aria-label'?: never;
  'aria-labelledby': string;
};

type PreviewTriggerOwnProps = {
  trigger: React.ReactElement;
  delay?: number;
  closeDelay?: number;
  open?: boolean;
  defaultOpen?: boolean;
  disabled?: boolean;
  placement?: MuxUIPlacement;
  offset?: number;
  crossOffset?: number;
  shouldFlip?: boolean;
  containerPadding?: number;
  onOpenChange?: (open: boolean) => void;
};

type PreviewTriggerProps = PreviewTriggerOwnProps & {
  children: React.ReactNode;
  className?: string;
} & OverlayAccessibleName;
